// WP-7.2 ReSTIR DI and GI on Vulkan: see include/fuse/renderer/restir/restir_gpu.hpp.
#include <fuse/renderer/restir/restir_gpu.hpp>

#include <fuse/renderer/rt/rt_caps.hpp>
#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp72.cmake from shaders/restir/*: kRestir<Kernel><Slang|Glsl>Spv and
// FUSE_RESTIR_{SLANG,GLSL} when every kernel of a language exists.
#include "restir_spv.h"
#endif

namespace fuse::renderer::restir {

namespace {
constexpr u32 kFrameStride = 512u; ///< ring slot size (>= sizeof(RestirFrameConstants), 256-aligned)
static_assert(sizeof(RestirFrameConstants) <= kFrameStride, "frame ring slot");
/// G-buffer attachments the prepare kernel reads (GBufferAttachment order): RT0 normal, RT1 albedo, RT4 depth.
constexpr u32 kGBufferAttachments[3] = {0u, 1u, 4u};
constexpr u8 kCs = rg::kStageCompute;

[[maybe_unused]] u32 groups(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }

/// Settings that change the chain structure (the history of another chain is meaningless).
bool sameStructure(const RestirSettings& a, const RestirSettings& b) {
    return a.di == b.di && a.gi == b.gi && a.unbiased == b.unbiased;
}

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

RestirCapabilities queryRestirCapabilities(const VulkanDevice* device) {
    RestirCapabilities caps{};
    if (device == nullptr) {
        return caps;
    }
#if defined(FUSE_VULKAN_BACKEND)
    const rt::RtCapabilities rt = rt::queryRtCapabilities(device);
    if (!rt.usable) {
        caps.reason = rt.reason;
        return caps;
    }
    caps.gpu = true;
    caps.reason = "ok";
#else
    caps.reason = "stub backend";
#endif
    return caps;
}

RestirGpu::~RestirGpu() { destroy(); }

void RestirGpu::setSettings(const RestirSettings& settings) {
    m_settings = restirSanitize(settings);
    m_settingsDirty = true;
}

bool RestirGpu::init(const RestirGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u ||
        desc.framesInFlight > kMaxSlots) {
        m_reason = "device / allocator / bindless / framesInFlight (1..8) missing";
        return false;
    }
    const RestirCapabilities caps = queryRestirCapabilities(desc.device);
    if (!caps.gpu) {
        m_reason = caps.reason;
        return false;
    }
    m_initialized = true; // destroy() releases partial state from here on
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride;
    ring.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress));
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "restir.frame";
    if (!m_desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr || m_frameRing.deviceAddress == 0u) {
        destroy();
        m_reason = "frame ring allocation failed";
        return false;
    }
    if (!ensureLightCapacity(std::max(desc.initialLights, 1u))) {
        destroy();
        m_reason = "light table allocation failed";
        return false;
    }
    if (!createPipelines(desc.language)) {
        destroy();
        m_reason = "restir kernels not built for the requested language / pipeline creation failed";
        return false;
    }
    if (desc.width > 0u && desc.height > 0u && !createBuffers(desc.width, desc.height)) {
        destroy();
        m_reason = "buffer allocation failed";
        return false;
    }
    m_settings = restirSanitize(m_settings);
    m_reason = "ok";
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void RestirGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    for (BindlessSlotHandle& slot : m_gbufferSlots) {
        if (slot.isValid()) {
            m_desc.bindless->unregisterSlot(slot);
        }
    }
    for (Buffer* b : {&m_state, &m_work, &m_output, &m_frameRing, &m_lightRing}) {
        if (b->handle != nullptr) {
            m_desc.allocator->destroyBuffer(*b);
        }
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void*& pipeline : m_pipelines) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
            pipeline = nullptr;
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_layoutHandle = nullptr;
    m_state = Buffer{};
    m_work = Buffer{};
    m_output = Buffer{};
    m_frameRing = Buffer{};
    m_lightRing = Buffer{};
    m_stateQueue = m_workQueue = m_outputQueue = m_lightQueue = rg::kNoQueue;
    m_frameAddress = 0;
    m_lightSlotBytes = 0;
    for (u32 i = 0; i < kMaxSlots; ++i) {
        m_lightSlotVersion[i] = 0;
        m_lightSlotValid[i] = false;
    }
    m_gbuffer = nullptr;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        m_gbufferImages[i] = nullptr;
        m_gbufferSlots[i] = BindlessSlotHandle{};
        m_gbufferHandles[i] = 0u;
    }
    for (Retired& r : m_retired) {
        r = Retired{};
    }
    m_layout = RestirBufferLayout{};
    m_recordCount = 0;
    m_history = false;
    m_language = "none";
    m_stats = RestirGpuStats{};
    m_initialized = false;
}

bool RestirGpu::createPipelines(RestirKernelLanguage language) {
#if defined(FUSE_VULKAN_BACKEND)
    Code k[kKernelCount]{};
    bool found = false;
#if defined(FUSE_RESTIR_SLANG)
    if (language == RestirKernelLanguage::Auto || language == RestirKernelLanguage::Slang) {
        k[kPrepare] = code(kRestirPrepareSlangSpv);
        k[kDiInitial] = code(kRestirDiInitialSlangSpv);
        k[kDiReuse] = code(kRestirDiReuseSlangSpv);
        k[kGiInitial] = code(kRestirGiInitialSlangSpv);
        k[kGiReuse] = code(kRestirGiReuseSlangSpv);
        k[kShade] = code(kRestirShadeSlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_RESTIR_GLSL)
    if (!found && (language == RestirKernelLanguage::Auto || language == RestirKernelLanguage::Glsl)) {
        k[kPrepare] = code(kRestirPrepareGlslSpv);
        k[kDiInitial] = code(kRestirDiInitialGlslSpv);
        k[kDiReuse] = code(kRestirDiReuseGlslSpv);
        k[kGiInitial] = code(kRestirGiInitialGlslSpv);
        k[kGiReuse] = code(kRestirGiReuseGlslSpv);
        k[kShade] = code(kRestirShadeGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    (void)language;
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(RestirPush)};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    for (u32 i = 0; i < kKernelCount; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = k[i].bytes;
        moduleInfo.pCode = k[i].words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        m_pipelines[i] = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    return true;
#else
    (void)language;
    return false;
#endif
}

bool RestirGpu::createBuffers(u32 width, u32 height) {
    const RestirBufferLayout layout = RestirBufferLayout::compute(width, height, m_desc.keepIntermediates);
    Buffer fresh[3]{};
    const u64 sizes[3] = {layout.stateBytes, layout.workBytes, layout.outputBytes};
    const char* names[3] = {"restir.state", "restir.work", "restir.output"};
    bool ok = true;
    for (u32 i = 0; i < 3u && ok; ++i) {
        BufferDesc d{};
        d.size = static_cast<usize>(sizes[i]);
        d.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress) |
                                           static_cast<u32>(BufferUsage::TransferSrc));
        d.memoryUsage = MemoryUsage::GpuOnly;
        d.name = names[i];
        ok = m_desc.allocator->createBuffer(d, fresh[i]) && fresh[i].deviceAddress != 0u;
    }
    if (!ok) {
        for (Buffer& b : fresh) {
            if (b.handle != nullptr) {
                m_desc.allocator->destroyBuffer(b);
            }
        }
        return false;
    }
    if (m_state.handle != nullptr || m_work.handle != nullptr || m_output.handle != nullptr) {
        Retired old{};
        old.buffers[0] = m_state;
        old.buffers[1] = m_work;
        old.buffers[2] = m_output;
        if (!retire(old)) {
            for (Buffer& b : fresh) {
                m_desc.allocator->destroyBuffer(b);
            }
            return false;
        }
    }
    m_state = fresh[0];
    m_work = fresh[1];
    m_output = fresh[2];
    m_stateQueue = m_workQueue = m_outputQueue = rg::kNoQueue;
    m_layout = layout;
    m_history = false;
    ++m_stats.rebuilds;
    return true;
}

bool RestirGpu::ensureLightCapacity(u32 lights) {
    const u64 slotBytes = (static_cast<u64>(lights) * sizeof(RestirLight) + 255u) & ~u64{255u};
    if (m_lightRing.handle != nullptr && slotBytes <= m_lightSlotBytes) {
        return true;
    }
    const u64 grown = std::max<u64>(slotBytes, m_lightSlotBytes * 2u);
    BufferDesc d{};
    d.size = static_cast<usize>(grown * m_desc.framesInFlight);
    d.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress));
    d.memoryUsage = MemoryUsage::CpuToGpu;
    d.name = "restir.lights";
    Buffer fresh{};
    if (!m_desc.allocator->createBuffer(d, fresh) || fresh.mapped == nullptr || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (m_lightRing.handle != nullptr) {
        Retired old{};
        old.buffers[3] = m_lightRing;
        if (!retire(old)) {
            m_desc.allocator->destroyBuffer(fresh);
            return false;
        }
    }
    m_lightRing = fresh;
    m_lightQueue = rg::kNoQueue;
    m_lightSlotBytes = grown;
    for (u32 i = 0; i < kMaxSlots; ++i) {
        m_lightSlotValid[i] = false;
    }
    return true;
}

bool RestirGpu::retire(const Retired& r) {
    for (Retired& slot : m_retired) {
        if (!slot.used) {
            slot = r;
            slot.serial = m_frameSerial;
            slot.used = true;
            return true;
        }
    }
    return false;
}

u32 RestirGpu::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    for (Retired& r : m_retired) {
        if (!r.used || r.serial > completedSerial) {
            continue;
        }
        for (BindlessSlotHandle& slot : r.slots) {
            if (slot.isValid()) {
                m_desc.bindless->unregisterSlot(slot);
            }
        }
        for (Buffer& b : r.buffers) {
            if (b.handle != nullptr) {
                m_desc.allocator->destroyBuffer(b);
            }
        }
        r = Retired{};
        ++collected;
    }
    return collected;
}

bool RestirGpu::bindGBuffer(const material_resolve::MaterialResolve& gbuffer) {
    bool changed = m_gbuffer != &gbuffer;
    for (u32 i = 0; i < kGBufferInputs && !changed; ++i) {
        changed = gbuffer.gbufferImage(kGBufferAttachments[i]).image != m_gbufferImages[i];
    }
    if (!changed) {
        return true;
    }
    Retired old{};
    bool any = false;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        old.slots[i] = m_gbufferSlots[i];
        any = any || m_gbufferSlots[i].isValid();
        m_gbufferSlots[i] = BindlessSlotHandle{};
        m_gbufferImages[i] = nullptr;
        m_gbufferHandles[i] = 0u;
    }
    if (any && !retire(old)) {
        return false;
    }
    m_gbuffer = &gbuffer;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        const Texture& image = gbuffer.gbufferImage(kGBufferAttachments[i]);
        if (image.image == nullptr) {
            return false;
        }
        m_gbufferSlots[i] = m_desc.bindless->registerTextureSlot(image, false);
        if (!m_gbufferSlots[i].isValid()) {
            return false;
        }
        m_gbufferImages[i] = image.image;
        m_gbufferHandles[i] = m_desc.bindless->shaderHandle(m_gbufferSlots[i]);
    }
    ++m_stats.gbufferBinds;
    return true;
}

bool RestirGpu::beginFrame(u64 frameSerial, const RestirFrameDesc& desc) {
    if (!m_initialized || desc.gbuffer == nullptr || desc.lightCount == 0u || desc.lights == nullptr || desc.tlasAddress == 0u ||
        desc.lightTreeHeader == 0u || desc.sceneHeader == 0u) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.passes = 0;
    const u32 w = desc.gbuffer->width();
    const u32 h = desc.gbuffer->height();
    if (w == 0u || h == 0u) {
        return false;
    }
    if ((w != m_layout.width || h != m_layout.height || m_state.handle == nullptr) && !createBuffers(w, h)) {
        return false;
    }
    if (!bindGBuffer(*desc.gbuffer)) {
        return false;
    }
    if (m_settingsDirty) {
        if (!sameStructure(m_active, m_settings)) {
            m_history = false;
        }
        m_active = m_settings;
        m_settingsDirty = false;
    }
    // Light table: this frame's ring slot, copied when it holds another version.
    if (!ensureLightCapacity(desc.lightCount)) {
        return false;
    }
    const u32 ringSlot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    m_lightOffset = static_cast<u64>(ringSlot) * m_lightSlotBytes;
    if (!m_lightSlotValid[ringSlot] || m_lightSlotVersion[ringSlot] != desc.lightsVersion || m_lightCount != desc.lightCount) {
        std::memcpy(static_cast<u8*>(m_lightRing.mapped) + m_lightOffset, desc.lights, static_cast<usize>(desc.lightCount) * sizeof(RestirLight));
        m_lightSlotValid[ringSlot] = true;
        m_lightSlotVersion[ringSlot] = desc.lightsVersion;
        ++m_stats.lightUploads;
    }
    if (m_lightCount != desc.lightCount) {
        for (u32 i = 0; i < kMaxSlots; ++i) {
            m_lightSlotValid[i] = i == ringSlot && m_lightSlotValid[i];
        }
        m_lightCount = desc.lightCount;
    }
    const bool history = m_history && !desc.reset;
    m_motion = desc.motion != 0u;
    RestirFrameParams params{};
    params.width = w;
    params.height = h;
    params.frameIndex = desc.frameIndex;
    params.seed = desc.seed;
    params.lightCount = desc.lightCount;
    params.history = history;
    params.motion = m_motion;
    if (!buildRestirFrameConstants(m_active, desc.camera, params, m_constants)) {
        return false;
    }
    m_slot ^= 1u;
    const u64 state = m_state.deviceAddress;
    const u32 cur = m_slot;
    const u32 prev = m_slot ^ 1u;
    m_constants.surfPos[0] = state + m_layout.surfPos[cur];
    m_constants.surfPos[1] = state + m_layout.surfPos[prev];
    m_constants.surfNormal[0] = state + m_layout.surfNormal[cur];
    m_constants.surfNormal[1] = state + m_layout.surfNormal[prev];
    m_constants.surfAlbedo[0] = state + m_layout.surfAlbedo[cur];
    m_constants.surfAlbedo[1] = state + m_layout.surfAlbedo[prev];
    m_constants.diHistory[0] = state + m_layout.diHistory[cur];
    m_constants.diHistory[1] = state + m_layout.diHistory[prev];
    m_constants.giHistory[0] = state + m_layout.giHistory[cur];
    m_constants.giHistory[1] = state + m_layout.giHistory[prev];
    m_constants.diSignal = m_output.deviceAddress + m_layout.diSignal;
    m_constants.giSignal = m_output.deviceAddress + m_layout.giSignal;
    m_constants.depth = m_output.deviceAddress + m_layout.depth;
    m_constants.motion = desc.motion;
    m_constants.lightTree = desc.lightTreeHeader;
    m_constants.lights = m_lightRing.deviceAddress + m_lightOffset;
    m_constants.tlas = desc.tlasAddress;
    m_constants.scene = desc.sceneHeader;
    m_constants.gbufferNormal = m_gbufferHandles[0];
    m_constants.gbufferAlbedo = m_gbufferHandles[1];
    m_constants.gbufferDepth = m_gbufferHandles[2];
    const u64 offset = (frameSerial % m_desc.framesInFlight) * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &m_constants, sizeof(m_constants));
    m_frameAddress = m_frameRing.deviceAddress + offset;
    m_stats.history = history;
    m_finalDi = kRestirInvalid;
    m_finalGi = kRestirInvalid;
    return true;
}

RestirGraphRefs RestirGpu::importInto(rg::Graph& graph) {
    RestirGraphRefs refs{};
    if (!m_initialized || m_state.handle == nullptr) {
        return refs;
    }
    refs.state = graph.importBuffer(rg::ImportedBuffer{m_state.handle, m_state.desc.size, m_stateQueue, &m_stateQueue, "restir.state"});
    refs.work = graph.importBuffer(rg::ImportedBuffer{m_work.handle, m_work.desc.size, m_workQueue, &m_workQueue, "restir.work"});
    refs.output =
        graph.importBuffer(rg::ImportedBuffer{m_output.handle, m_output.desc.size, m_outputQueue, &m_outputQueue, "restir.output"});
    refs.lights =
        graph.importBuffer(rg::ImportedBuffer{m_lightRing.handle, m_lightRing.desc.size, m_lightQueue, &m_lightQueue, "restir.lights"});
    return refs;
}

bool RestirGpu::addPasses(rg::Graph& graph, const RestirGraphRefs& refs, const RestirGraphInputs& in) {
    if (!m_initialized || !refs.state.valid() || !refs.work.valid() || !refs.output.valid() || !refs.lights.valid() ||
        !in.tlas.valid() || !in.lightTree.tree.valid() || in.gbuffer == nullptr || !in.scene.header.valid() ||
        (m_motion && !in.motion.valid())) {
        return false;
    }
    for (const u32 attachment : kGBufferAttachments) {
        if (!in.gbuffer->gbuffer[attachment].valid()) {
            return false;
        }
    }
    const RestirSettings& s = m_active;
    const u64 pixels = static_cast<u64>(m_layout.width) * m_layout.height;
    const rg::BufferRange lightRange{m_lightOffset, static_cast<u64>(m_lightCount) * sizeof(RestirLight)};
    const u64 work = m_work.deviceAddress;
    auto record = [&](u32 kernel, const char* name, u64 src, u64 dst, u64 aux, u32 mode, u32 iteration) -> rg::PassBuilder {
        PassRecord& r = m_records[m_recordCount++];
        r = PassRecord{};
        r.self = this;
        r.kernel = kernel;
        r.push.frame = m_frameAddress;
        r.push.src = src;
        r.push.dst = dst;
        r.push.aux = aux;
        r.push.mode = mode;
        r.push.iteration = iteration;
        ++m_stats.passes;
        return graph.addPass(name, &RestirGpu::recordDispatch, &r);
    };
    // Rays + the light sampler + the light table.
    auto useTracing = [&](rg::PassBuilder& pass, bool sceneTables) {
        pass.use(in.tlas, rg::Access::AccelerationStructureRead, {}, kCs);
        pass.use(in.lightTree.tree, rg::Access::StorageRead, in.lightTree.range, kCs);
        pass.use(refs.lights, rg::Access::StorageRead, lightRange, kCs);
        if (sceneTables) {
            gpu_scene::GpuScene::useAll(pass, in.scene, rg::Access::StorageRead, kCs);
            if (in.scene.indices.valid()) {
                pass.use(in.scene.indices, rg::Access::StorageRead, {}, kCs);
            }
        }
    };
    const u32 passCount = 2u + (s.di ? 2u + s.diSpatialIterations : 0u) + (s.gi ? 2u + s.giSpatialIterations : 0u);
    if (m_recordCount + passCount > kMaxPasses) {
        return false;
    }
    {
        rg::PassBuilder pass = record(kPrepare, "restir.prepare", 0u, 0u, 0u, 0u, 0u);
        for (const u32 attachment : kGBufferAttachments) {
            pass.use(in.gbuffer->gbuffer[attachment], rg::Access::SampledRead, {}, kCs);
        }
        pass.use(refs.state, rg::Access::StorageReadWrite, {}, kCs);
    }
    if (s.di) {
        u32 last = 0u;
        {
            rg::PassBuilder pass = record(kDiInitial, "restir.di.initial", 0u, work + m_layout.diStage[0], 0u, 0u, 0u);
            pass.use(refs.state, rg::Access::StorageRead, {}, kCs).use(refs.work, rg::Access::StorageReadWrite, {}, kCs);
            useTracing(pass, false);
        }
        auto reuse = [&](u32 stage, u32 mode, u32 iteration, const char* name) {
            rg::PassBuilder pass = record(kDiReuse, name, work + m_layout.diStage[last], work + m_layout.diStage[stage], 0u, mode, iteration);
            pass.use(refs.state, rg::Access::StorageRead, {}, kCs).use(refs.work, rg::Access::StorageReadWrite, {}, kCs);
            if (mode == kRestirModeTemporal && m_motion) {
                pass.use(in.motion, rg::Access::StorageRead, {}, kCs);
            }
            useTracing(pass, false);
            last = stage;
        };
        if (s.diTemporal) {
            reuse(1u, kRestirModeTemporal, 0u, "restir.di.temporal");
        }
        for (u32 i = 0; i < s.diSpatialIterations; ++i) {
            reuse(2u + i, kRestirModeSpatial, i, "restir.di.spatial");
        }
        m_finalDi = last;
    }
    if (s.gi) {
        u32 last = 0u;
        {
            rg::PassBuilder pass =
                record(kGiInitial, "restir.gi.initial", 0u, work + m_layout.giStage[0], in.dump.valid() ? in.dumpAddress : 0u, 0u, 0u);
            pass.use(refs.state, rg::Access::StorageRead, {}, kCs).use(refs.work, rg::Access::StorageReadWrite, {}, kCs);
            useTracing(pass, true);
            if (in.dump.valid()) {
                pass.use(in.dump, rg::Access::StorageWrite, rg::BufferRange{0, pixels * sizeof(RestirGiHitRecord)}, kCs);
            }
        }
        auto reuse = [&](u32 stage, u32 mode, u32 iteration, const char* name) {
            rg::PassBuilder pass = record(kGiReuse, name, work + m_layout.giStage[last], work + m_layout.giStage[stage], 0u, mode, iteration);
            pass.use(refs.state, rg::Access::StorageRead, {}, kCs).use(refs.work, rg::Access::StorageReadWrite, {}, kCs);
            if (mode == kRestirModeTemporal && m_motion) {
                pass.use(in.motion, rg::Access::StorageRead, {}, kCs);
            }
            useTracing(pass, false);
            last = stage;
        };
        if (s.giTemporal) {
            reuse(1u, kRestirModeTemporal, 0u, "restir.gi.temporal");
        }
        for (u32 i = 0; i < s.giSpatialIterations; ++i) {
            reuse(2u + i, kRestirModeSpatial, i, "restir.gi.spatial");
        }
        m_finalGi = last;
    }
    {
        const u64 di = m_finalDi != kRestirInvalid ? work + m_layout.diStage[m_finalDi] : 0u;
        const u64 gi = m_finalGi != kRestirInvalid ? work + m_layout.giStage[m_finalGi] : 0u;
        rg::PassBuilder pass = record(kShade, "restir.shade", di, 0u, gi, 0u, 0u);
        pass.use(refs.state, rg::Access::StorageReadWrite, {}, kCs).use(refs.work, rg::Access::StorageRead, {}, kCs);
        pass.use(refs.output, rg::Access::StorageWrite, {}, kCs);
        useTracing(pass, false);
    }
    m_history = true;
    return true;
}

u64 RestirGpu::diSignalAddress() const { return m_output.deviceAddress != 0u ? m_output.deviceAddress + m_layout.diSignal : 0u; }
u64 RestirGpu::giSignalAddress() const { return m_output.deviceAddress != 0u ? m_output.deviceAddress + m_layout.giSignal : 0u; }
u64 RestirGpu::depthAddress() const { return m_output.deviceAddress != 0u ? m_output.deviceAddress + m_layout.depth : 0u; }
u64 RestirGpu::normalAddress() const { return m_state.deviceAddress != 0u ? m_state.deviceAddress + m_layout.surfNormal[m_slot] : 0u; }

void RestirGpu::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const RestirGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipelines[r.kernel]));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(RestirPush),
                       &r.push);
    vkCmdDispatch(cmd, groups(self.m_layout.width, kRestirTile), groups(self.m_layout.height, kRestirTile), 1u);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::restir
